class Solution { public: int minMoves(vector<int>& nums,int limit){vector<int> difference(2*limit+2);for(int left=0,right=nums.size()-1;left<right;++left,--right){int low=min(nums[left],nums[right]),high=max(nums[left],nums[right]),sum=low+high;difference[2]+=2;--difference[low+1];--difference[sum];++difference[sum+1];++difference[high+limit+1];}int moves=0,answer=INT_MAX;for(int sum=2;sum<=2*limit;++sum){moves+=difference[sum];answer=min(answer,moves);}return answer;} };
